-- 03_migracion.sql  |  MySQL 8.0.19+  |  Migración COMPLETA de la hoja 'Base De Datos' (8208 filas con datos, 2022-01-01 a 2025-03-28) -> modelo normalizado.
-- Archivo generado con privado/generar_migracion.py: nombres reales ya reemplazados por seudónimos; en el staging solo hay datos primarios.
-- Estrategia: (1) staging con las columnas originales (sin fórmulas ni horas calculadas), ya depurado:
--               subcódigos viejos 4.x -> 5.x, errores de digitación en referencias, vacíos -> 'Sin especificar';
--             (2) n_registro = fila 'madre' (la que trae pacas); las filas de continuación (solo paros) apuntan a ella;
--             (3) registro_produccion desde las filas madre; 'secuencia' numera registros idénticos del mismo día (antes de oct-2023 el Excel no distingue turno ni operaria);
--             (4) 'despivotar' las 18 columnas de código en filas de paro (CROSS JOIN codigo_paro + CASE), sumando el mismo código/subcódigo repetido;
--             (5) verificar integridad. Las filas que NO se cargan están en docs/filas_no_cargadas.csv.

DROP TABLE IF EXISTS stg_excel;
CREATE TABLE stg_excel (
  n_fila INT, n_registro INT, secuencia SMALLINT, fecha DATE, maquina VARCHAR(20), operario VARCHAR(80), referencia VARCHAR(60), turno VARCHAR(30),
  pacas INT, horas NUMERIC(4,2),
  cod1 INT, cod2 INT, cod3 INT, cod4 INT, cod5 INT, cod6 INT, cod7 INT, cod8 INT, cod9 INT, cod10 INT, cod11 INT, cod12 INT, cod13 INT, cod14 INT, cod15 INT, cod16 INT, cod17 INT, cod18 INT,
  subcod1 VARCHAR(10), subcod3 VARCHAR(10), subcod5 VARCHAR(10), personal VARCHAR(80)
);


-- Meta por hora: NO existe en el libro. Se define aquí (supuesto del equipo). Cambie los valores si conoce la meta real.
-- 52 = la meta manuscrita en el formato físico del P-MTO-22 (Vinilos_2, Rojo 125cc).
DROP TABLE IF EXISTS stg_meta;
CREATE TABLE stg_meta (maquina VARCHAR(20) PRIMARY KEY, meta_por_hora INT NOT NULL);

-- 2) registro_produccion: una fila por cada fila madre del staging.
SELECT s.fecha, m.id_maquina, t.id_turno, r.id_referencia, p.id_persona, s.secuencia, s.pacas, s.horas, sm.meta_por_hora
FROM stg_excel s
JOIN maquina m    ON m.nombre = s.maquina
JOIN turno t      ON t.nombre = s.turno
JOIN referencia r ON r.nombre = s.referencia
JOIN persona p    ON p.nombre = s.operario AND p.rol = 'OPERARIA'
JOIN stg_meta sm  ON sm.maquina = s.maquina
WHERE s.n_fila = s.n_registro;

-- 3) paro: una fila por cada código con minutos > 0 (se elimina el grupo repetitivo de 18 columnas).
--    Cada fila del staging se cruza con los 18 códigos; CASE elige la columna 'codN' que corresponde.
--    Se suma el mismo código/subcódigo si el Excel lo repite en la fila madre y en sus continuaciones.
SELECT rp.id_registro, u.codigo, sc.id_subcodigo, SUM(u.minutos), MAX(pe.id_persona)
FROM (
  SELECT s.n_registro, s.personal, c.id_codigo_paro AS codigo,
         CASE c.id_codigo_paro
           WHEN 1 THEN s.cod1
           WHEN 2 THEN s.cod2
           WHEN 3 THEN s.cod3
           WHEN 4 THEN s.cod4
           WHEN 5 THEN s.cod5
           WHEN 6 THEN s.cod6
           WHEN 7 THEN s.cod7
           WHEN 8 THEN s.cod8
           WHEN 9 THEN s.cod9
           WHEN 10 THEN s.cod10
           WHEN 11 THEN s.cod11
           WHEN 12 THEN s.cod12
           WHEN 13 THEN s.cod13
           WHEN 14 THEN s.cod14
           WHEN 15 THEN s.cod15
           WHEN 16 THEN s.cod16
           WHEN 17 THEN s.cod17
           WHEN 18 THEN s.cod18
         END AS minutos,
         CASE c.id_codigo_paro WHEN 1 THEN s.subcod1 WHEN 3 THEN s.subcod3 WHEN 5 THEN s.subcod5 END AS sub
  FROM stg_excel s CROSS JOIN codigo_paro c
) u
JOIN stg_excel h    ON h.n_fila = u.n_registro
JOIN maquina m      ON m.nombre = h.maquina
JOIN turno t        ON t.nombre = h.turno
JOIN referencia r   ON r.nombre = h.referencia
JOIN persona o      ON o.nombre = h.operario AND o.rol = 'OPERARIA'
JOIN registro_produccion rp ON rp.fecha = h.fecha AND rp.id_maquina = m.id_maquina AND rp.id_turno = t.id_turno
                           AND rp.id_referencia = r.id_referencia AND rp.id_operaria = o.id_persona AND rp.secuencia = h.secuencia
LEFT JOIN subcodigo_paro sc ON sc.codigo = u.sub AND sc.id_codigo_paro = u.codigo
LEFT JOIN persona pe ON pe.nombre = u.personal AND u.codigo = 5
WHERE COALESCE(u.minutos,0) > 0
GROUP BY rp.id_registro, u.codigo, sc.id_subcodigo;

-- 4) Verificación de integridad (esperado: registros=4756, paros=15495, minutos=477881, pacas=378727; cada par _excel/_bd debe coincidir).
SELECT (SELECT COUNT(*) FROM stg_excel WHERE n_fila = n_registro) AS registros_excel,
       (SELECT COUNT(*) FROM registro_produccion) AS registros_bd,
       (SELECT SUM(COALESCE(cod1,0)+COALESCE(cod2,0)+COALESCE(cod3,0)+COALESCE(cod4,0)+COALESCE(cod5,0)+COALESCE(cod6,0)+COALESCE(cod7,0)+COALESCE(cod8,0)+COALESCE(cod9,0)+COALESCE(cod10,0)+COALESCE(cod11,0)+COALESCE(cod12,0)+COALESCE(cod13,0)+COALESCE(cod14,0)+COALESCE(cod15,0)+COALESCE(cod16,0)+COALESCE(cod17,0)+COALESCE(cod18,0)) FROM stg_excel) AS minutos_excel,
       (SELECT SUM(minutos) FROM paro) AS minutos_bd,
       (SELECT SUM(pacas) FROM stg_excel) AS pacas_excel,
       (SELECT SUM(pacas_producidas) FROM registro_produccion) AS pacas_bd,
       (SELECT COUNT(*) FROM paro) AS paros_bd;

-- Subcódigos del Excel que no existen en el catálogo (debe devolver 0 filas).
SELECT DISTINCT s AS subcodigo_sin_catalogo FROM (SELECT subcod1 AS s FROM stg_excel UNION SELECT subcod3 FROM stg_excel UNION SELECT subcod5 FROM stg_excel) t
WHERE s IS NOT NULL AND s NOT IN (SELECT codigo FROM subcodigo_paro);
